import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

import { sceneLogic } from 'scenes/sceneLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sceneWidthLogicValues {
    activeSceneId: string | null // sceneLogic
    isSceneFullWidth: boolean
    narrowSceneIds: Record<string, boolean>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sceneWidthLogicActions {
    toggleSceneFullWidth: (sceneId: string) => {
        sceneId: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sceneWidthLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        isSceneFullWidth: (narrowSceneIds: Record<string, boolean>, activeSceneId: string | null) => boolean
    }
}

export type sceneWidthLogicType = MakeLogicType<
    sceneWidthLogicValues,
    sceneWidthLogicActions,
    Record<string, any>,
    sceneWidthLogicMeta
>

export const sceneWidthLogic = kea<sceneWidthLogicType>([
    // pinned: the path is the localStorage key; renaming it resets every user's choice
    path(['layout', 'scenes', 'sceneWidthLogic']),
    connect(() => ({
        values: [sceneLogic, ['activeSceneId']],
    })),
    actions({
        toggleSceneFullWidth: (sceneId: string) => ({ sceneId }),
    }),
    reducers({
        narrowSceneIds: [
            {} as Record<string, boolean>,
            { persist: true },
            {
                toggleSceneFullWidth: (state, { sceneId }) => {
                    const { [sceneId]: wasNarrow, ...rest } = state
                    return wasNarrow ? rest : { ...rest, [sceneId]: true }
                },
            },
        ],
    }),
    selectors({
        isSceneFullWidth: [
            (s) => [s.narrowSceneIds, s.activeSceneId],
            (narrowSceneIds: Record<string, boolean>, activeSceneId: string | null): boolean =>
                !activeSceneId || !narrowSceneIds[activeSceneId],
        ],
    }),
    listeners(({ values }) => ({
        toggleSceneFullWidth: ({ sceneId }) => {
            posthog.capture('scene full width toggled', {
                scene: sceneId,
                full_width: !values.narrowSceneIds[sceneId],
            })
        },
    })),
])
